package android.util;import java.util.*;public class StatsEvent{public int atom;public List<Integer>values=new ArrayList<>();public List<String>annotations=new ArrayList<>();public boolean pooled;public static Builder newBuilder(){return new Builder();}public static class Builder{StatsEvent e=new StatsEvent();public Builder setAtomId(int id){e.atom=id;return this;}public Builder writeInt(int i){e.values.add(i);return this;}public Builder addBooleanAnnotation(byte id,boolean b){e.annotations.add(e.values.size()+":"+id+":"+b);return this;}public void usePooledBuffer(){e.pooled=true;}public StatsEvent build(){return e;}}}